select case when c.age >= 61 then 'high' when c.age >= 40 then 'mid' else 'low' end as age_bucket, month(c.signup_date) as signup_month, count(distinct s.monthly_fee) as unique_statuss from subscriptions s join customers c on s.customer_id = c.id group by case when c.age >= 61 then 'high' when c.age >= 40 then 'mid' else 'low' end, month(c.signup_date) order by unique_statuss desc
